WITH latest_rows AS (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14'), period_value AS (SELECT mktcode,tgtcode,MAX_BY(volume,bizdate) AS value FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate>=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' WEEK) AND bizdate<=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' DAY) GROUP BY mktcode,tgtcode), volume_rank AS (SELECT mktcode,tgtcode,ROW_NUMBER() OVER(ORDER BY volume DESC,mktcode,tgtcode) AS r0 FROM latest_rows), turnover_rank AS (SELECT mktcode,tgtcode,ROW_NUMBER() OVER(ORDER BY turnover DESC,mktcode,tgtcode) AS r1 FROM latest_rows) SELECT a.mktcode,a.tgtcode,a.bizdate FROM latest_rows a JOIN period_value p ON p.mktcode=a.mktcode AND p.tgtcode=a.tgtcode JOIN volume_rank v ON v.mktcode=a.mktcode AND v.tgtcode=a.tgtcode JOIN turnover_rank t ON t.mktcode=a.mktcode AND t.tgtcode=a.tgtcode WHERE p.value>0 AND v.r0/NULLIF(t.r1,0)<=1;
